    # Use COMPOSIO_SEARCH_TOOLS to find the correct tools
    search_result = session.execute(
        tool_slug="COMPOSIO_SEARCH_TOOLS",
        arguments={
            "queries": [
                {
                    "use_case": "create a file in a GitHub repository"
                },
                {
                    "use_case": "post a message to a Slack channel"
                }
            ],
            "session": {
                "generate_id": True
            }
        }
    )

    print(f"Search result status: {search_result.status}")

    # Parse the search result to get the session_id and tool information
    if search_result.data:
        print(f"Search result data: {json.dumps(search_result.data, indent=2)[:1000]}")

        # Extract session_id
        session_id = None
        if isinstance(search_result.data, dict):
            session_id = search_result.data.get('session_id')

        print(f"Session ID: {session_id}")

        # Look for the tool slugs in the search result
        github_tool_slug = None
        slack_tool_slug = None

        if isinstance(search_result.data, dict):
            results = search_result.data.get('results', [])
            for result in results:
                tools = result.get('tools', [])
                for tool in tools:
                    tool_slug = tool.get('tool_slug', '')
                    if 'GITHUB' in tool_slug.upper() and 'CREATE' in tool_slug.upper() and 'FILE' in tool_slug.upper():
                        github_tool_slug = tool_slug
                        print(f"Found GitHub tool: {github_tool_slug}")
                    if 'SLACK' in tool_slug.upper() and ('POST' in tool_slug.upper() or 'SEND' in tool_slug.upper()) and 'MESSAGE' in tool_slug.upper():
                        slack_tool_slug = tool_slug
                        print(f"Found Slack tool: {slack_tool_slug}")

        if not github_tool_slug or not slack_tool_slug:
            print("\nCould not find exact tool matches. Available tools in search result:")
            if isinstance(search_result.data, dict):
                results = search_result.data.get('results', [])
                for result in results:
                    tools = result.get('tools', [])
                    for tool in tools:
                        print(f"  - {tool.get('tool_slug', 'UNKNOWN')}: {tool.get('description', 'No description')[:80]}")

        # Step 2: Execute the tools using COMPOSIO_MULTI_EXECUTE_TOOL
        if session_id and github_tool_slug and slack_tool_slug:
            print(f"\nStep 2: Executing tools in parallel using COMPOSIO_MULTI_EXECUTE_TOOL...")

            multi_execute_result = session.execute(
                tool_slug="COMPOSIO_MULTI_EXECUTE_TOOL",
                arguments={
                    "tools": [
                        {
                            "tool_slug": github_tool_slug,
                            "arguments": {
                                "owner": "zealt-user01",
                                "repo": f"multi-test-{TRIAL_ID}",
                                "path": "harbor.txt",
                                "content": f"Harbor trial {TRIAL_ID}",
                                "message": f"Create harbor.txt for trial {TRIAL_ID}"
                            }
                        },
                        {
                            "tool_slug": slack_tool_slug,
                            "arguments": {
                                "channel": "general",
                                "text": f"File harbor.txt created in trial {TRIAL_ID}"
                            }
                        }
                    ],
                    "sync_response_to_workbench": False,
                    "session_id": session_id,
                    "thought": "Create a file in GitHub repository and post notification to Slack in parallel"
                }
            )

            print(f"Multi-execute result status: {multi_execute_result.status}")
            if multi_execute_result.data:
                print(f"Multi-execute result: {json.dumps(multi_execute_result.data, indent=2)[:2000]}")
            if multi_execute_result.error:
                print(f"Multi-execute error: {multi_execute_result.error}")
        else:
            print("\nSkipping execution - missing session_id or tool slugs")
    else:
        print(f"Search failed. Error: {search_result.error}")

    print("\nMulti-tool execution completed!")

if __name__ == "__main__":
    main()

